<script lang="ts">
 import {onMount} from 'svelte';import {drafts,saveDraft,cards,savePhoto,photos,type Draft,type ObjectCard,type PhotoDraft} from '$lib/offline';import {translator} from '$lib/app-i18n';import type {Language} from '$lib/i18n';
 let lang=$state<Language>('de'),tenantId=$state(''),items=$state<Draft[]>([]),objects=$state<ObjectCard[]>([]),files=$state<PhotoDraft[]>([]),body=$state(''),title=$state(''),message=$state(''),lot=$state(''),vineyard=$state(''),sample=$state(''),parameter=$state('temperature'),value=$state(''),unit=$state(''),method=$state(''),date=$state(''),hours=$state('0'),area=$state(''),description=$state(''),operator=$state('');let t=$derived(translator(lang));let lots=$derived(objects.filter(c=>c.kind==='lots')),vineyards=$derived(objects.filter(c=>c.kind==='vineyards'));
 async function refresh(){if(tenantId){items=await drafts(tenantId);objects=await cards(tenantId);files=await photos(tenantId);}}
 onMount(()=>{tenantId=localStorage.getItem('vinea-active-winery')??'';const requested=localStorage.getItem('vinea-language');lang=['de','en','it','fr'].includes(requested??'')?requested as Language:'de';refresh();});
 async function save(type:string){try{const refs={...(lot?{lot_id:lot}:{}),...(vineyard?{vineyard_id:vineyard}:{})};const command=type==='note_add'?{type,body,...refs}:type==='task_create'?{type,title,...refs}:type==='analysis_add'?{type,lot_id:lot,sample_code:sample,sampled_at:new Date(date).toISOString(),parameter,value,unit,method,measured_at:new Date(date).toISOString(),quality:'measured'}:{type,vineyard_id:vineyard,kind:'other',description,performed_at:new Date(date).toISOString(),hours,area_ha:area,quantity:'0',unit:'none',operator};await saveDraft(tenantId,command);await refresh();message=t('draftSaved');}catch{message=t('INVALID_INPUT');}}
 async function photo(event:Event){const file=(event.currentTarget as HTMLInputElement).files?.[0];if(!file)return;try{await savePhoto(tenantId,file,{lot_id:lot||undefined,vineyard_id:vineyard||undefined});await refresh();message=t('draftSaved');}catch{message=t('INVALID_ASSET');}}
</script>
<main><h1>Vinea · {t('draft')}</h1><p>{t('offline')}</p>{#if tenantId}<section><h2>{t('offlineCards')}</h2>{#each objects as card}<details><summary>{card.record.code} · {card.record.name} · {t('capturedAt')} {card.capturedAt}</summary><pre>{JSON.stringify({object:card.record,...card.related},null,2)}</pre>{#each card.related.tasks??[] as task}<p>{task.title} · {t(task.status)} <button onclick={async()=>{await saveDraft(tenantId,{type:'task_update',task_id:task.id,status:'done',expected_version:task.version});await refresh();message=t('draftSaved');}}>{t('done')}</button></p>{/each}</details>{/each}</section><div class="grid"><label>{t('lot_id')}<select bind:value={lot}><option value="">—</option>{#each lots as c}<option value={c.record.id}>{c.record.code}</option>{/each}</select></label><label>{t('vineyard_id')}<select bind:value={vineyard}><option value="">—</option>{#each vineyards as c}<option value={c.record.id}>{c.record.code}</option>{/each}</select></label></div><form onsubmit={(e)=>{e.preventDefault();save('note_add');}}><label>{t('body')}<textarea bind:value={body} required maxlength="5000"></textarea></label><button>{t('note_add')}</button></form><form onsubmit={(e)=>{e.preventDefault();save('task_create');}}><label>{t('title')}<input bind:value={title} required maxlength="160" /></label><button>{t('task_create')}</button></form><form onsubmit={(e)=>{e.preventDefault();save('analysis_add');}}><h2>{t('offlineMeasurement')}</h2><label>{t('sample_code')}<input required bind:value={sample} /></label><label>{t('parameter')}<select bind:value={parameter}>{#each ['temperature','alcohol','sugar','acidity','ph','free_so2'] as p}<option value={p}>{p==='ph'?'pH':t(p)}</option>{/each}</select></label><label>{t('value')}<input required bind:value={value} inputmode="decimal" /></label><label>{t('unit')}<input required bind:value={unit} /></label><label>{t('method')}<input required bind:value={method} /></label><label>{t('measured_at')}<input type="datetime-local" required bind:value={date} /></label><button disabled={!lot}>{t('analysis_add')}</button></form><form onsubmit={(e)=>{e.preventDefault();save('field_record');}}><h2>{t('offlineWork')}</h2><label>{t('description')}<textarea required bind:value={description}></textarea></label><label>{t('operator')}<input required bind:value={operator} /></label><label>{t('performed_at')}<input type="datetime-local" required bind:value={date} /></label><label>{t('hours')}<input required bind:value={hours} /></label><label>{t('area_ha')}<input required bind:value={area} /></label><button disabled={!vineyard}>{t('field_record')}</button></form><label>{t('upload')}<input type="file" accept="image/png,image/jpeg,application/pdf" onchange={photo} /></label><p role="status">{message}</p><ul>{#each items as item}<li>{t(String(item.command.type))} · {item.capturedAt} · {t(item.state)}</li>{/each}{#each files as file}<li>{file.file.name} · {file.capturedAt}</li>{/each}</ul>{/if}<a href="/app/today">{t('sync')}</a></main>
<style>:global(body){font-family:system-ui;background:#f7f7f3;color:#263b32}main{max-width:680px;margin:40px auto;padding:25px}h1{font:36px Georgia}form{margin:30px 0;display:grid;gap:14px;border-top:1px solid #d9dfd5;padding-top:20px}label{display:grid;gap:8px}input,select,textarea{padding:12px;border:1px solid #d9dfd5;border-radius:7px;font:inherit}button{padding:12px;background:#285741;color:white;border:0;border-radius:7px}pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:400px;overflow:auto;font-size:11px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}</style>
